import React from "react";
import MessageBubble from "./MessageBubble";

const ChatWindow = ({ messages }) => {
  return (
    <div
      style={{
        height: "350px",
        border: "1px solid #ccc",
        padding: "10px",
        overflowY: "auto",
        marginBottom: "10px",
        background: "#fafafa"
      }}
    >
      {messages.map((msg, index) => (
        <MessageBubble
          key={index}
          sender={msg.sender}
          text={msg.text}
        />
      ))}
    </div>
  );
};

export default ChatWindow;
